//! `phdb serve` (D313, #1397): one process serving a database over gRPC, HTTP/JSON and
//! remote MCP. This build holds only the network API's contract (ICR 0112): the messages and
//! services generated from `proto/pigeonhole/v1/*.proto`. The server itself follows.

/// The network API, v1: generated by `tools/protogen` from `proto/pigeonhole/v1/`, never
/// edited by hand (CI regenerates it and fails on a difference).
#[allow(
    dead_code,
    missing_docs,
    unreachable_pub,
    clippy::all,
    clippy::pedantic,
    rustdoc::all
)]
pub(crate) mod proto {
    include!("proto/pigeonhole.v1.rs");
    include!("proto/pigeonhole.v1.serde.rs");
}

#[cfg(test)]
mod tests;
